-- Table: report_snapshot
-- Source: accounting_admin_db.sql (6. Accounting expense, reconciliation, and period closing)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS report_snapshot (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    snapshot_number VARCHAR(50)  NOT NULL UNIQUE,
    report_code     VARCHAR(50)  NOT NULL,
    report_name     VARCHAR(150) NOT NULL,
    period_id       BIGINT       NOT NULL REFERENCES accounting_period(id),
    closing_id      BIGINT REFERENCES accounting_period_closing(id),
    as_of_date      DATE         NOT NULL,
    version         INTEGER      NOT NULL DEFAULT 1 CHECK (version > 0),
    status          VARCHAR(20)  NOT NULL DEFAULT 'draft'
                    CHECK (status IN ('draft', 'final', 'void')),
    parameters      JSONB        NOT NULL DEFAULT '{}'::jsonb,
    payload         JSONB        NOT NULL DEFAULT '{}'::jsonb,
    checksum        TEXT,
    generated_by    BIGINT REFERENCES masterdata_user(id),
    generated_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    notes           TEXT,
    UNIQUE (report_code, period_id, version)
);
